  "/prozess": { titel: "Projektprozess", prio: 0.7, freq: "monthly" },
  "/warum-oekoinvest": { titel: "Warum ÖkoInvest", prio: 0.6, freq: "monthly" },
  // Zielgruppen
  "/flaeche-verpachten": { titel: "Fläche verpachten", prio: 0.9, freq: "monthly" },
