  "/kontakt": { titel: "Kontakt", prio: 0.6, freq: "yearly" },
  "/termin": { titel: "Termin", prio: 0.6, freq: "monthly" },
  // Rechtstexte (Entwürfe filtert die Sitemap über src/lib/indexsteuerung.js)
  "/impressum": { titel: "Impressum", prio: 0.2, freq: "yearly", datum: RECHT },
  "/datenschutz": { titel: "Datenschutz", prio: 0.2, freq: "yearly", datum: RECHT },
  "/nutzungsbedingungen": { titel: "Nutzungsbedingungen", prio: 0.3, freq: "yearly", datum: RECHT },
  "/barrierefreiheit": { titel: "Barrierefreiheit", prio: 0.2, freq: "yearly", datum: RECHT },
  "/bedingungen/banken": { titel: "Bedingungen Banken", index: false },
  "/bedingungen/energiebeschaffung": { titel: "Bedingungen Energiebeschaffung", index: false },
  "/bedingungen/lieferanten": { titel: "Bedingungen Lieferanten", index: false },
  "/bedingungen/projektboerse": { titel: "Bedingungen Projektbörse", index: false },
});

export const SITEMAP_START = START;

const VERMERK_DE = Object.freeze({
  stand: "2026-10-03",
  grundlage: "Seite rendert eine eigene Fassung für Deutschland (16 Bundesländer zuerst, Landesrecht DE); Inhalte aus Welle 1",
  pruefer: "TODO-E6",
});

const VERMERK_AT = Object.freeze({
  stand: "2026-10-03",
  grundlage: "Seite rendert eine eigene Fassung für Österreich (Recht AT, Begriffe, ohne ungeprüfte Pachtwerte); fachlich überarbeitet in Welle 1",
  pruefer: "TODO-E6",
});

const VERMERK_CH = Object.freeze({
  stand: "2026-10-04",
  grundlage: "Seite rendert eine eigene Fassung für die Schweiz (RPG Art. 24ter, Bewilligung Gemeinde/Kanton, HEIV, LEG/vZEV; ohne ungeprüfte Pacht- und Kostenwerte); Quellen in src/data/laender/ch/ und src/data/regionen/schweiz.js",
  pruefer: "TODO-E6",
});

/**
 * Echter Länderinhalt je Land (Muster-Schlüssel → Freigabe-Vermerk).
 * Nur eintragen, wenn die Seite für das Land WIRKLICH anderen, geprüften Inhalt rendert
 * (über inhaltFuer()/landDerAnfrage(), src/lib/land/inhalte.js) – nicht nur dieselbe Seite
 * mit anderem Präfix.
 */
export const LAENDERINHALT = Object.freeze({
  DE: Object.freeze({
    "/regionen": VERMERK_DE,
  }),
  AT: Object.freeze({
    "/flaechencheck": VERMERK_AT,
    "/energiegemeinschaften": VERMERK_AT,
    "/regionen": VERMERK_AT,
  }),
  CH: Object.freeze({
    "/freiflaeche": VERMERK_CH,
    "/energiegemeinschaften": VERMERK_CH,
    "/agri-pv": VERMERK_CH,
  }),
});

/** Regionsseiten: Land je Slug aus den Stammdaten der Regionen. */
export const REGION_LAND = Object.freeze(Object.fromEntries(REGIONEN_META.map((r) => [r.slug, r.land])));

/** Schlüssel einer Regionsseite ("tirol" → "/regionen/tirol"). */
export const regionSchluessel = (slug) => "/regionen/" + slug;

const MUSTER = Object.keys(SEITEN)
  .filter((k) => SEITEN[k].dynamisch)
  .map((k) => ({ k, basis: k.slice(0, k.indexOf("/[")) }));

/**
 * Pfad ohne Präfix → Registereintrag. Dynamische Seiten (/regionen/tirol) werden auf ihr Muster
 * ("/regionen/[slug]") abgebildet; Regionen nur mit bekanntem Slug.
 * @returns {{ schluessel: string, muster: string, eintrag: object } | null}
 */
export function seiteFuer(schluesselRoh) {
  if (typeof schluesselRoh !== "string") return null;
  const schluessel = nurPfad(schluesselRoh);
  if (Object.hasOwn(SEITEN, schluessel) && !SEITEN[schluessel].dynamisch) return { schluessel, muster: schluessel, eintrag: SEITEN[schluessel] };
  for (const { k, basis } of MUSTER) {
    if (!schluessel.startsWith(`${basis}/`)) continue;
    const slug = schluessel.slice(basis.length + 1);
    if (!/^[a-z0-9-]+$/.test(slug)) continue;
    if (k === "/regionen/[slug]" && !Object.hasOwn(REGION_LAND, slug)) continue;
    return { schluessel, muster: k, eintrag: SEITEN[k] };
  }
  return null;
}

/** Hat dieser präfixlose Pfad eine Länderfassung (/de…, /at…, /ch…)? */
export const hatLandfassung = (schluessel) => !!seiteFuer(schluessel);

/** Gibt es für die Seite im Land echten, freigegebenen Länderinhalt? */
export function eigenerInhalt(schluessel, land) {
  const s = seiteFuer(schluessel);
  if (!s || !LAND_CODES.includes(land)) return false;
  return Object.hasOwn(LAENDERINHALT[land], s.muster);
}

/** Länder mit eigenem Inhalt für eine Seite (LAND_CODES-Reihenfolge). */
export const laenderMitInhalt = (schluessel) => LAND_CODES.filter((l) => eigenerInhalt(schluessel, l));

/**
 * Indexierbar? land null = gemeinsame Seite (indexiert, außer index: false);
 * Länderfassung nur mit eigenem Inhalt (sonst noindex bis zur Freigabe).
 */
export function indexierbar(schluessel, land = null) {
  const s = seiteFuer(schluessel);
  if (!s || s.eintrag.index === false) return false;
  return land ? eigenerInhalt(schluessel, land) : true;
}

/** Alle konkreten Schlüssel (Regionen aufgelöst; Ratgeber und Exposés nicht). */
export function alleSchluessel() {
  const liste = [];
  for (const k of Object.keys(SEITEN)) {
    if (k === "/regionen/[slug]") liste.push(...Object.keys(REGION_LAND).map(regionSchluessel));
    else if (!SEITEN[k].dynamisch) liste.push(k);
  }
  return liste;
}
// src/lib/land/seite.js – Land einer Seite auf dem Server (nutzt react/cache und next/navigation)
//
// Getrennt von index.js, damit node:test, next.config.mjs, Middleware und Client-Komponenten die
// reine Länderlogik ohne Server-Funktionen laden können.
//
// Jede öffentliche Seite (src/app/(stamm)/…/page.js) ist zugleich ihre Länderfassung: Die Route
// src/app/(laender)/[land]/…/page.js exportiert genau diese Seite weiter, Next.js reicht dabei
// params.land ("de" | "at" | "ch") durch. Die Seite ruft am Anfang
//
//   const land = await seitenLand(params);          // "DE" | "AT" | "CH" | null (= gemeinsam)
//
// und exportiert ihre Metadaten über
//
//   export const generateMetadata = seitenMetadata("/rechner/pacht", metadata);
//
// Tiefer liegende Server-Komponenten (z. B. RechnerSeite) lesen das Land danach mit
// landDerAnfrage() – ohne es durchreichen zu müssen. Client-Komponenten nutzen useLand()
// (src/components/Land/useLand.js), das Land kommt dort aus dem Root-Layout.

import { cache } from "react";
import { notFound } from "next/navigation";
import { landAusPraefix } from "./laender.js";
import { alternates, fassungIndexierbar, ogLocale } from "./pfad.js";
import { spracheOder } from "../sprache/sprachen.js";
import { setzeLandQuelle, uebersetze } from "../sprache/woerterbuch.js";
import { schreibweiseFuer } from "./schreibweise.js";

/** Speicher je Anfrage (React cache): Land und Sprache der gerade gerenderten Seite. */
const anfrage = cache(() => ({ land: null, sprache: "de", gesetzt: false }));

// Server-Komponenten rufen uebersetze(TEXTE, sprache) ohne Land: Das Land der Anfrage kommt von
// hier (Schweizer Schreibweise ohne „ß“ auf /ch und /en/ch, src/lib/land/schreibweise.js).
setzeLandQuelle(() => anfrage().land);

/**
 * Sprache aus den Routenparametern: Die englischen Routen (src/app/(en)/en/…, erzeugt mit
 * scripts/landfassungen.mjs) reichen params.sprache = "en" an dieselbe Seitenkomponente durch
 * (src/lib/sprache/route.js). Ohne Angabe: Deutsch.
 */
export const spracheAusParams = (p) => spracheOder(p?.sprache);

/**
 * Land aus den Routenparametern. Ohne params.land: gemeinsame Seite (null).
 * Unbekanntes Präfix → 404. Merkt sich das Land für landDerAnfrage().
 * @param {Promise<object>|object} params
 * @returns {Promise<"DE"|"AT"|"CH"|null>}
 */
export async function seitenLand(params) {
  const p = (await params) || {};
  let land = null;
  if (p.land !== undefined) {
    land = landAusPraefix(p.land);
    if (!land) notFound();
  }
  const a = anfrage();
  a.land = land;
  a.sprache = spracheAusParams(p);
  a.gesetzt = true;
  return land;
}

/**
 * Land der aktuellen Seite für Server-Komponenten unterhalb der Seite.
 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst null = gemeinsam).
 */
export function landDerAnfrage() {
  return anfrage().land;
}

/**
 * Sprache der aktuellen Seite ("de" | "en") für Server-Komponenten unterhalb der Seite.
 * Nur gültig, nachdem die Seite seitenLand(params) aufgerufen hat (sonst "de").
 */
export function spracheDerAnfrage() {
  return anfrage().sprache;
}

/**
 * generateMetadata für eine öffentliche Seite (gemeinsam, Länderfassung, englische Fassung):
 * übernimmt die Basis-Metadaten und setzt canonical, hreflang, og:url und og:locale.
 * Noindex bekommen Länderfassungen ohne eigenen Länderinhalt (Register src/lib/land/seiten.js)
 * und englische Fassungen, die noch nicht übersetzt sind (src/lib/sprache/seiten.js).
 * @param {string | ((p: object) => string)} schluessel Pfad ohne Präfix (bei [slug]-Routen aus params)
 * @param {object | ((land: string|null, p: object) => object|Promise<object>)} basis  p.sprache = "de" | "en"
 * @param {{ en?: object | ((de: object) => object) }} [woerterbuch] englische Metadaten (title,
 *   description, openGraph.title …), tief über die deutschen gelegt (uebersetze()).
 */
export function seitenMetadata(schluessel, basis, woerterbuch = {}) {
  return async function generateMetadata({ params }) {
    const p = (await params) || {};
    const land = p.land !== undefined ? landAusPraefix(p.land) : null;
    const sprache = spracheAusParams(p);
    const konkret = typeof schluessel === "function" ? schluessel(p) : schluessel;
    const roh = (typeof basis === "function" ? await basis(land, p) : basis) || {};
    const b = sprache === "en" && woerterbuch?.en ? uebersetze({ de: roh, en: woerterbuch.en }, "en") : roh;
    const a = alternates(konkret, land, { languages: b.alternates?.languages, sprache });
    const index = land || sprache !== "de" ? fassungIndexierbar(konkret, land, sprache) : null;
    const locale = land || sprache !== "de" ? { locale: ogLocale(land, sprache) } : {};
    return schreibweiseFuer({
      ...b,
      alternates: { ...(b.alternates || {}), ...a, ...(a.languages ? {} : { languages: undefined }) },
      ...(b.openGraph ? { openGraph: { ...b.openGraph, url: a.canonical, ...locale } } : {}),
      ...(index === false ? { robots: { index: false, follow: true } } : {}),
    }, land);
  };
}
"use client";

// Link, der in Sprache und Land der Seite bleibt (Länder- und Sprachmodell):
//   auf /at/…     href="/rechner/pacht" → /at/rechner/pacht
//   auf /en/at/…  href="/rechner/pacht" → /en/at/rechner/pacht
//   auf /en/…     href="/rechner/pacht" → /en/rechner/pacht
//   gemeinsam     href="/rechner/pacht" → /rechner/pacht
// Pfade ohne Länder-/Sprachfassung (Portal, Login …), externe Links und Anker bleiben unverändert.
// Ausdrücklich gesetzte Länderpräfixe ("/at/…") bleiben im Land, bekommen auf englischen Seiten
// aber das Sprachpräfix; ausdrücklich gesetzte Sprachpräfixe ("/en/…") behalten ihre Sprache und
// bekommen nur das Land der Seite, wenn sie keines tragen ("/en" auf /at → /en/at).
// Ersetzt `next/link` in allen öffentlichen Komponenten (gleiche Props, gleiches <a>).

import NextLink from "next/link";
import { forwardRef } from "react";
import { PRAEFIX_MUSTER, SPRACH_MUSTER, landAusPfad, pfad } from "@/lib/land";
import { useSeitenLand } from "./LandKontext";
import { useSprache } from "@/components/Sprache/SpracheKontext";

/** href in Sprache und Land der Seite auflösen (String oder UrlObject). */
export function useLandHref(href) {
  const land = useSeitenLand();
  const sprache = useSprache();
  return landHref(href, land, sprache);
}

function zielPfad(p, land, sprache) {
  // Ausdrückliches Sprachpräfix ohne Land ("/en" im Menü „English“) bleibt im Land der Seite: auf /at → /en/at
  if (SPRACH_MUSTER.test(p)) return land && !landAusPfad(p).land ? pfad(p, land, landAusPfad(p).sprache) : p;
  if (PRAEFIX_MUSTER.test(p)) return sprache === "en" ? pfad(p, landAusPfad(p).land, "en") : p;
  return pfad(p, land, sprache);
}

export function landHref(href, land, sprache = "de") {
  if (typeof href === "string") return zielPfad(href, land, sprache);
  if (href && typeof href === "object" && typeof href.pathname === "string") return { ...href, pathname: zielPfad(href.pathname, land, sprache) };
  return href;
}

const Link = forwardRef(function Link({ href, ...rest }, ref) {
  const ziel = useLandHref(href);
  return <NextLink ref={ref} href={ziel} {...rest} />;
});

export default Link;
// Bausteine für Länderinhalte (Ländermodell) – ohne Hooks, also in Server- und Client-
// Komponenten nutzbar. Das Land kommt vom Aufrufer (Server: seitenLand()/landDerAnfrage(),
// Client: useLand()). Regeln und Beispiele: src/lib/land/inhalte.js.
//
//   <LandHinweis land="CH" />                         Block statt ungeprüfter Werte
//   <LandHinweis land="AT" thema="Pachtwerte" zeile /> kompakt, z. B. in einer Werteliste
//   <GiltFuer />                                      dezent „gilt für Deutschland“
//   <LandWerte land={land} geprueft={["DE"]}>…</LandWerte>
//       DE: Werte · gemeinsame Seite: Werte + „gilt für Deutschland“ · AT/CH: LandHinweis
// Englisch (Sprachmodell): Die Bausteine schreiben ihre festen Texte über <T> selbst englisch.
// Eigene Texte englisch mitgeben: <LandHinweis land text="…" textEn="…" thema="Pachtwerte" themaEn="Lease rates" />.

import { Clock } from "lucide-react";
import Link from "@/components/Land/Link";
import { cn } from "@/components/ui/cn";
import { LAENDER, landCode, landHinweisText, landHinweisTextEn, zahlenModus } from "@/lib/land";
import T from "@/components/Sprache/T";

/** Hinweis statt Werten, die für das Land noch nicht an der Quelle geprüft sind. */
export function LandHinweis({ land, thema = "Rechenwerte", themaEn, zeile = false, text, textEn, className }) {
  const l = landCode(land);
  if (!l) return null;
  // Englisch: eigener Text nur, wenn textEn mitkommt – sonst bleibt der eigene deutsche Text stehen
  const satz = <T de={text || `${landHinweisText(l, thema)}.`} en={text ? textEn : `${landHinweisTextEn(l, themaEn)}.`} />;
  if (zeile) {
    return (
      <p className={cn("flex items-start gap-2 text-[13.5px] leading-relaxed text-ink-600", className)} data-land-hinweis={l}>
        <Clock aria-hidden="true" className="mt-0.5 h-4 w-4 shrink-0 text-navy-500" />
        <span>
          {satz}{" "}
          <Link href="/kontakt" className="font-semibold text-ov-700 underline decoration-ov-300 underline-offset-2 hover:decoration-current">
            <T de="Persönlich anfragen" en="Ask us directly" />
          </Link>
        </span>
      </p>
    );
  }
  return (
    <div role="status" className={cn("rounded-3xl bg-sand-50 p-6 ring-1 ring-ink-200/70 md:p-8", className)} data-land-hinweis={l}>
      <p className="flex items-center gap-2 text-[13px] font-semibold uppercase tracking-[0.08em] text-ink-500">
        <Clock aria-hidden="true" className="h-4 w-4 text-navy-500" /> <T de={LAENDER[l].name} en={LAENDER[l].en.name} />
      </p>
      <p className="mt-3 max-w-prose text-[15px] leading-relaxed text-ink-700">{satz}</p>
      <Link
        href="/kontakt"
        className="mt-4 inline-flex min-h-[40px] items-center justify-center rounded-full bg-ov-600 px-4 text-[14px] font-semibold text-white transition-colors hover:bg-ov-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ov-500 focus-visible:ring-offset-2"
      >
        <T de="Vorhaben persönlich besprechen" en="Discuss your project with us" />
      </Link>
    </div>
  );
}

