      rechner={<WechselCheck fakten={fakten} />}
      erklaerung={
        <div>
          <h2 className="ov-h2 text-ink-900">{en ? "How the check works" : "So prüfen wir"}</h2>
          <p className="mt-4 text-[16.5px] leading-relaxed text-ink-600">
            {en
