              ["Anbieterwechsel", "ohne Neuanmeldung"],
              ["Modellwechsel", "Neuanmeldung aller Zählpunkte"],
              ["Netzbetreiberübergreifend", "voraussichtlich ab April 2027"],
              ["Parallellauf vor dem Stichtag", "ein Monat"],
