              {/* Preisposten */}
              <dl className={cn("mt-6 divide-y rounded-2xl px-4", dunkel ? "divide-white/10 bg-white/[0.06] ring-1 ring-white/10" : "divide-ink-100 bg-sand-50 ring-1 ring-ink-200/60")}>
