              <Button href="#anfrage" variant={dunkel ? "primary" : "secondary"} block pfeil className="mt-auto translate-y-0 pt-0 [margin-top:max(1.5rem,auto)]">
                {t.anfragen(p.titel)}
              </Button>
            </article>
          </Reveal>
        );
      })}
    </ul>
  );
}

/** Vermerk zur Freigabe der Beträge (öffentlich, ehrlich). */
export function FreigabeVermerk({ en = false }) {
