// Paket B7: ganze Seiten fotografieren und den Wechsel-Check durchklicken.
// node b7-eg.tmp.mjs <basis> <out> <breite> <modus: voll|check> <pfade...>
import { chromium } from "playwright";
import { mkdirSync } from "node:fs";
const [basis, out, breiteArg, modus, ...pfade] = process.argv.slice(2);
mkdirSync(out, { recursive: true });
const w = Number(breiteArg);
const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: w, height: w < 700 ? 844 : 900 }, reducedMotion: "reduce" });
await ctx.addCookies([{ name: "cookie-einwilligung", value: "notwendig", url: basis }]).catch(() => {});
const page = await ctx.newPage();
const fehler = [];
page.on("pageerror", (e) => fehler.push(String(e)));
page.on("console", (m) => m.type() === "error" && fehler.push(m.text()));
for (const pfad of pfade) {
  fehler.length = 0;
  const r = await page.goto(basis + pfad, { waitUntil: "load", timeout: 240000 });
  await page.waitForTimeout(1200);
  await page.locator("button", { hasText: /Nur notwendige|Only necessary|Necessary only/ }).first().click({ timeout: 2500 }).catch(() => {});
  const name = pfad.replace(/[^a-z0-9]+/gi, "_").replace(/^_|_$/g, "");
  if (modus === "check") {
    // Antworten: Modell, Zählpunkte, Verwaltung, Probleme (mehrfach), Vertrag, EDA, Vorhaben (mehrfach)
    const klick = async (txt) => { await page.locator("label", { hasText: txt }).first().click(); await page.waitForTimeout(400); };
    const weiter = async () => { await page.locator("#rechner button.bg-ov-600").first().click(); await page.waitForTimeout(400); };
    const en = pfad.startsWith("/en");
    await klick(en ? "Local EEG" : "EEG lokal");
    await klick(en ? "21 to 100" : "21 bis 100");
    await klick(en ? "By volunteers with spreadsheets" : "Ehrenamtlich mit Tabellen");
    await klick(en ? "Too much volunteer work" : "Zu viel Arbeit im Ehrenamt");
    await klick(en ? "Contracts not yet adapted" : "Verträge noch nicht ans ElWG");
    await weiter();
    await klick(en ? "Fixed term" : "Feste Laufzeit");
    await klick(en ? "Only our provider" : "Nur unser Anbieter");
    await klick(en ? "Members from other grid areas" : "Mitglieder aus anderen Netzgebieten");
    await weiter();
    await page.waitForTimeout(800);
    const el = page.locator("#rechner");
    await el.screenshot({ path: `${out}/w${w}-${name}-ergebnis.png` });
  } else {
    await page.evaluate(async () => { for (let y = 0; y < document.body.scrollHeight; y += 600) { window.scrollTo(0, y); await new Promise((r) => setTimeout(r, 60)); } window.scrollTo(0, 0); });
    await page.waitForTimeout(500);
    await page.screenshot({ path: `${out}/w${w}-${name}-voll.png`, fullPage: true });
  }
  const breite = await page.evaluate(() => document.documentElement.scrollWidth);
  console.log(`${r?.status()} w${w} ${pfad} breite=${breite}${breite > w ? " ÜBERLAUF" : ""} fehler=${fehler.length}`);
  fehler.slice(0, 3).forEach((f) => console.log("   ! " + f.slice(0, 200)));
}
await browser.close();
EOF
